create table if not exists public.ils_professional_assignment_e2e_release_gate_decisions (id uuid primary key default gen_random_uuid(),path_code text not null default 'PROFESSIONAL_ASSIGNMENT_E2E',decision text not null check(decision in ('GO','HOLD','FAIL')),genuine_verified_evidence_count integer not null default 0,synthetic_evidence_count integer not null default 0,hostile_tests_passed integer not null default 0,hostile_tests_failed integer not null default 0,destructive_attempts integer not null default 0,reason text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_e2e_release_gate_decisions enable row level security; alter table public.ils_professional_assignment_e2e_release_gate_decisions force row level security; revoke all on public.ils_professional_assignment_e2e_release_gate_decisions from public,anon,authenticated; create or replace function public.ils_professional_assignment_e2e_release_gate_evaluate() returns table(decision text,genuine_verified_evidence_count integer,synthetic_evidence_count integer,hostile_tests_passed integer,hostile_tests_failed integer,destructive_attempts integer,reason text) language plpgsql security definer set search_path=public as $$ declare v_genuine integer:=0; v_synth integer:=0; v_pass integer:=0; v_fail integer:=0; v_dest integer:=0; v_decision text; v_reason text; begin if to_regclass('public.ils_e2e_evidence') is not null then execute 'select count(*) filter (where evidence_class=''VERIFIED'' and coalesce(source_type,''REAL'')<>''SYNTHETIC''), count(*) filter (where coalesce(source_type,''REAL'')=''SYNTHETIC'') from public.ils_e2e_evidence' into v_genuine,v_synth; end if; select count(*) filter (where passed),count(*) filter (where not passed),count(*) filter (where destructive_attempted) into v_pass,v_fail,v_dest from public.ils_professional_assignment_e2e_hostile_results; if v_genuine>=1 and v_fail=0 and v_dest=0 then v_decision:='GO'; v_reason:='Genuine verified professional assignment E2E evidence present and hostile safety controls pass'; else v_decision:='HOLD'; v_reason:='Genuine verified professional assignment E2E evidence is required; synthetic evidence cannot satisfy release proof'; end if; insert into public.ils_professional_assignment_e2e_release_gate_decisions(decision,genuine_verified_evidence_count,synthetic_evidence_count,hostile_tests_passed,hostile_tests_failed,destructive_attempts,reason) values(v_decision,v_genuine,v_synth,v_pass,v_fail,v_dest,v_reason); return query select v_decision,v_genuine,v_synth,v_pass,v_fail,v_dest,v_reason; end; $$; revoke all on function public.ils_professional_assignment_e2e_release_gate_evaluate() from public,anon,authenticated; grant execute on function public.ils_professional_assignment_e2e_release_gate_evaluate() to service_role;